"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[851],{851:function(e,t,o){o.d(t,{places:function(){return n}});let a=e=>"https://picsum.photos/seed/cs".concat(e,"/800/600"),n=[{id:"1",name:"先锋书店\xb7长沙店",nameEn:"Librairie Avant-Garde",category:"bookstore",district:"yuelu",address:"岳麓区麓山南路溁湾镇",description:"光线穿过高挑的书架落在地板上，整个下午就这样消失了。独立出版物选品很有品味，在长沙很难找到这么好的书店气氛。咖啡区安静，适合一个人待着。",photos:[a(1),a(2)],coverPhoto:a(1),studyFriendly:!0,tags:["独立书店","选品精良","安静","有咖啡"],personalRating:5,openHours:"10:00 – 22:00",priceRange:"\xa5",featured:!0,createdAt:new Date("2024-01-15"),lat:28.192,lng:112.92},{id:"2",name:"弘道书院",nameEn:"Hongdao Academy",category:"bookstore",district:"tianxin",address:"天心区书院路123号",description:"藏在老街里的书院，有种穿越感。古典建筑配现代书目，氛围极好。周末常有读书分享活动，老板很有趣。",photos:[a(3)],coverPhoto:a(3),studyFriendly:!0,tags:["古典建筑","文化氛围","讲座"],personalRating:4,openHours:"09:00 – 21:00",priceRange:"\xa5",featured:!1,createdAt:new Date("2024-02-01"),lat:28.198,lng:112.985},{id:"3",name:"费大厨湘菜馆",nameEn:"Chef Fei's Hunan Kitchen",category:"hunan-cuisine",district:"furong",address:"芙蓉区五一大道附近",description:"辣椒炒肉是我来长沙第一家就去的店，后来又去了三次。食材很新鲜，火候到位，没有为外地游客调淡的那种妥协。",photos:[a(4),a(5)],coverPhoto:a(4),studyFriendly:!1,tags:["辣椒炒肉","土匪猪蹄","本地人爱去"],personalRating:5,openHours:"11:00–14:00，17:00–21:00",priceRange:"\xa5\xa5",featured:!0,createdAt:new Date("2024-01-20"),lat:28.185,lng:112.995},{id:"4",name:"火宫殿",nameEn:"Huo Gong Dian",category:"hunan-cuisine",district:"tianxin",address:"天心区坡子街127号",description:"长沙的精神坐标。臭豆腐、糖油粑粑、猪血丸子，在小摊前排队是一种仪式感。本地人也天天来，不用担心是不是网红打卡。",photos:[a(6)],coverPhoto:a(6),studyFriendly:!1,tags:["臭豆腐","老长沙味道","必去"],personalRating:5,openHours:"08:00 – 22:00",priceRange:"\xa5",featured:!1,createdAt:new Date("2024-01-10"),lat:28.197,lng:113.003},{id:"5",name:"和平粉店",nameEn:"Heping Noodle Shop",category:"noodles",district:"kaifu",address:"开福区和平路段",description:"早上七点，碗里的汤还在冒热气。米粉是本地宽粉，码子选牛肉，汤底鲜而不腻。每次回长沙必吃的第一顿。",photos:[a(7)],coverPhoto:a(7),studyFriendly:!1,tags:["米粉","早餐","老长沙"],personalRating:5,openHours:"06:30 – 14:00",priceRange:"\xa5",featured:!1,createdAt:new Date("2024-03-05"),lat:28.215,lng:112.99},{id:"6",name:"TAZA 面包工坊",nameEn:"TAZA Boulangerie",category:"bakery",district:"yuelu",address:"岳麓区含浦街道附近",description:"可颂层次分明，咸蛋黄系列出乎意料地好。下午的阳光从窗子打进来，配一杯咖啡，很适合一个人待一整个下午。",photos:[a(8),a(9)],coverPhoto:a(8),studyFriendly:!0,tags:["可颂","精品咖啡","自然光"],personalRating:4,openHours:"09:00 – 21:00",priceRange:"\xa5\xa5",featured:!1,createdAt:new Date("2024-02-14"),lat:28.163,lng:112.905},{id:"7",name:"若比邻书店",nameEn:"Neighbour Books",category:"bookstore",district:"yuhua",address:"雨花区某购物广场内",description:"像藏在购物中心里的秘密花园。文学、艺术类书目为主，定期有插画师驻场活动。买了三本书两张明信片，心满意足。",photos:[a(11)],coverPhoto:a(11),studyFriendly:!0,tags:["文学","艺术","插画","选品独特"],personalRating:4,openHours:"10:00 – 22:00",priceRange:"\xa5",featured:!1,createdAt:new Date("2024-03-10"),lat:28.165,lng:113.02},{id:"8",name:"曹记面馆",nameEn:"Cao's Noodle House",category:"noodles",district:"tianxin",address:"天心区南门口附近",description:"口味虾米粉在长沙是一种信仰。这家汤底是自己熬的，每天限量。我那天等了二十分钟，完全值得。",photos:[a(12)],coverPhoto:a(12),studyFriendly:!1,tags:["口味虾米粉","限量","排队"],personalRating:4,openHours:"11:00 – 售完为止",priceRange:"\xa5",featured:!1,createdAt:new Date("2024-02-20"),lat:28.197,lng:113.001},{id:"9",name:"岳麓山书肆",nameEn:"Yuelu Mountain Bookshop",category:"bookstore",district:"yuelu",address:"岳麓区岳麓山景区内",description:"在山里的书店，进门是古树的气息。爬山累了在这里坐下翻书，是长沙才有的体验。湖湘文化类书目这里最全。",photos:[a(13),a(14)],coverPhoto:a(13),studyFriendly:!0,tags:["山中书店","湖湘文化","自然环境"],personalRating:5,openHours:"09:00 – 18:00",priceRange:"\xa5",featured:!0,createdAt:new Date("2024-01-25"),lat:28.183,lng:112.93},{id:"10",name:"目田书店",nameEn:"Reedom Bookstore",category:"bookstore",district:"furong",address:"芙蓉中路605号花炮大楼1703室",description:"隐匿于老旧花炮大楼17层的宝藏独立书店。由曹璞工作室设计，空间错落通透，藏书独特而不流俗，更有“悲伤省”小酒馆相伴，是长沙文艺青年的精神角落。",photos:[a(15),a(16)],coverPhoto:a(15),studyFriendly:!0,tags:["独立书店","老友记感","闹中取静","艺术设计"],personalRating:5,openHours:"13:00 – 21:00",priceRange:"\xa5",featured:!0,createdAt:new Date("2024-05-24"),lat:28.203,lng:112.986},{id:"11",name:"乐之书店\xb7橘子洲店",nameEn:"Lezhi Bookstore (Juzi Island)",category:"bookstore",district:"yuelu",address:"岳麓区橘子洲景区内美孚洋行旧址",description:"坐落于橘子洲百年老洋楼（美孚洋行旧址）内的“最美书店”。融合了美式复古与中式歇山顶，藏书极富湖湘特色，是集阅读、咖啡与百年历史风华于一体的江心文化客厅。",photos:[a(17),a(18)],coverPhoto:a(17),studyFriendly:!0,tags:["百年洋楼","橘子洲","最美书店","湖湘文化"],personalRating:5,openHours:"09:30 – 17:30",priceRange:"\xa5\xa5",featured:!0,createdAt:new Date("2024-05-24"),lat:28.182,lng:112.961},{id:"12",name:"阿克梅书店",nameEn:"Acme Books",category:"bookstore",district:"yuelu",address:"岳麓区麓山南路492号2楼",description:"名字源自俄国白银时代“阿克梅派”诗歌，Logo为诗人阿赫玛托娃肖像。主打“陌生的美，普世的义”，选品兼顾文学与学术，充满主理人独特的阅读品味，是大学城爱书人的灵魂自留地。",photos:[a(19),a(20)],coverPhoto:a(19),studyFriendly:!0,tags:["阿克梅派","诗歌与哲学","大学城","学术选品"],personalRating:5,openHours:"10:00 – 22:00",priceRange:"\xa5",featured:!1,createdAt:new Date("2024-05-24"),lat:28.176,lng:112.934},{id:"13",name:"回望书店",nameEn:"Huiwang Bookstore",category:"bookstore",district:"yuelu",address:"岳麓区麓山南路矿山研究院1村1栋103",description:"“人生前驰，时有回望”。隐藏在矿研院老小区宿舍楼里的纯粹独立书店。专注于哲学、社科与诗歌，支持自由拆封阅读，不喧嚣、不迎合，常举办小众影展和读书会。",photos:[a(21),a(22)],coverPhoto:a(21),studyFriendly:!0,tags:["哲学社科","独立书店","老小区","纯粹阅读"],personalRating:5,openHours:"12:00 – 21:00",priceRange:"\xa5",featured:!1,createdAt:new Date("2024-05-24"),lat:28.188,lng:112.935},{id:"14",name:"止间书店\xb7建湘路店",nameEn:"Zhijian Bookstore",category:"bookstore",district:"kaifu",address:"开福区建湘北路270号芙蓉城2楼",description:"“守心一处，止步此间”。曾被评为长沙“最美书店”的人文艺术空间。原木色调与典雅后现代风格交融，不仅售书，更承载了丰富的讲座、文化沙龙与生活美学。",photos:[a(23),a(24)],coverPhoto:a(23),studyFriendly:!0,tags:["城市客厅","人文书店","空间美学","文化沙龙"],personalRating:4,openHours:"10:00 – 22:00",priceRange:"\xa5\xa5",featured:!1,createdAt:new Date("2024-05-24"),lat:28.201,lng:112.985},{id:"15",name:"拙鱼书房",nameEn:"Zhuoyu Study",category:"bookstore",district:"yuelu",address:"岳麓区潇湘北路1088号渔人码头6栋2楼",description:"“大巧若拙，大智若愚”。位于湘江畔渔人码头的绝美江景书房。由意大利设计师乔凡尼\xb7费拉拉设计，内部陈设大量清代古匾、旧瓷与明清古砖，江风佛面，极富历史厚重与生活温度。",photos:[a(25),a(26)],coverPhoto:a(25),studyFriendly:!0,tags:["临江书房","渔人码头","古建陈设","慢生活"],personalRating:5,openHours:"10:00 – 22:00",priceRange:"\xa5\xa5",featured:!0,createdAt:new Date("2024-05-24"),lat:28.239,lng:112.969}]}}]);